args.CommandLine:
node -e "
const fs = require('fs');
const chunks = JSON.parse(fs.readFileSync('scratch/subscreens_transcript.json', 'utf8'));

chunks.forEach(c => {
  console.log('Step:', c.step, 'Length:', c.content.length);
  const subs = ['subscreen-security', 'subscreen-notifications', 'subscreen-data', 'subscreen-categories', 'subscreen-accounts', 'subscreen-templates', 'subscreen-sync', 'subscreen-family', 'subscreen-feedback', 'subscreen-legal'];
  subs.forEach(s => {
    if (c.content.includes(s)) console.log('  - Has ' + s);
  });
});
"
